#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    string largestTimeFromDigits(vector<int>& arr) {
        string res = "";
        sort(arr.begin(), arr.end());
        do {
            int h = arr[0] * 10 + arr[1], m = arr[2] * 10 + arr[3];
            if (h < 24 && m < 60) {
                char buf[6];
                sprintf(buf, "%02d:%02d", h, m);
                res = max(res, string(buf));
            }
        } while (next_permutation(arr.begin(), arr.end()));
        return res;
    }
};
